package bo.com.ganadero.seguridad.application;
import bo.com.ganadero.seguridad.domain.*;import bo.com.ganadero.shared.security.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Service public class CrearRolUseCase{private final RolRepository repository;private final UserContext context;private final ApplicationEventPublisher events;public CrearRolUseCase(RolRepository repository,UserContext context,ApplicationEventPublisher events){this.repository=repository;this.context=context;this.events=events;}
 @Transactional public Rol execute(String codigo,String nombre,String descripcion){CurrentUser actor=context.requirePermission("ROL_CREAR");Rol role=repository.create(actor.empresaId(),codigo.toUpperCase(java.util.Locale.ROOT),nombre,descripcion,actor.userId());events.publishEvent(new SeguridadAuditEvent(actor.empresaId(),actor.userId(),"CREAR","ROL",role.id(),Instant.now()));return role;}}
